<?php
declare(strict_types=1);
function prod_generated_json(int $project,string $bytes,?string &$stored,mixed &$lock):int{
 $root=cc_storage(true);$lock=fopen($root.'/.quota.lock','c');if(!$lock||is_link($root.'/.quota.lock')||!flock($lock,LOCK_EX))crm_fail(503,'Хранилище занято.');chmod($root.'/.quota.lock',0600);$used=0;foreach(new DirectoryIterator($root) as $entry){if($entry->isDot()||$entry->getFilename()==='.quota.lock')continue;if($entry->isLink()||!$entry->isFile())crm_fail(503,'Хранилище требует проверки.');$used+=$entry->getSize();}cc_capacity($used,strlen($bytes),min(536870912,max(1,(int)(config()['collaboration_total_max_bytes']??104857600))),disk_free_space($root));
 $key=bin2hex(random_bytes(32));$path=$root.'/'.$key;$f=@fopen($path,'xb');if(!$f)crm_fail(503,'Не удалось создать пакет.');$stored=$path;try{if(!chmod($path,0600))crm_fail(503,'Не удалось защитить пакет.');$remaining=$bytes;while($remaining!==''){$n=fwrite($f,$remaining);if(!$n)crm_fail(503,'Не удалось сохранить пакет.');$remaining=substr($remaining,$n);}}finally{fclose($f);}if(hash_file('sha256',$path)!==hash('sha256',$bytes))crm_fail(503,'Пакет не прошёл проверку записи.');
 crm_query("INSERT INTO nd_cc_files(project_id,storage_key,display_name,mime,size_bytes,checksum,actor_type,actor_id,visibility) VALUES (?,?,?,'application/json',?,?,'owner',1,'internal')",[$project,$key,'Результат-проекта-'.$project.'.json',strlen($bytes),hash('sha256',$bytes)]);return (int)db()->lastInsertId();
}
function prod_package(int $run,array $d):array{
 $stored=null;$lock=null;try{return crm_idempotent('production:package:'.$run,$d,function()use($run,&$stored,&$lock){$r=prod_run($run,true);$p=prod_plan((int)$r['plan_id']);prod_current_source($p,true);$bundle=prod_bundle($run);$qa=crm_query('SELECT * FROM nd_prod_qa_reports WHERE run_id=? ORDER BY id DESC LIMIT 1 FOR UPDATE',[$run])->fetch();if(!$qa||$qa['verdict']!=='PASS'||!hash_equals($qa['bundle_hash'],$bundle['hash'])||$r['state']!=='READY')crm_fail(409,'Нет полного QA PASS для точного набора. Недоступные проверки нельзя пропустить.');
  $spec=cc_revision(['type'=>'owner','id'=>1],(int)$p['spec_revision_id']);$manifest=['format'=>'neurodelo-delivery-json-v1','project_id'=>(int)$p['project_id'],'order_id'=>(int)$p['order_id'],'specification'=>array_intersect_key($spec['fields'],array_flip(['title','goal','requirements','acceptance'])),'files'=>array_values($bundle['files']),'checksums'=>array_map(fn($f)=>hash('sha256',$f['content']),$bundle['files']),'provenance'=>$bundle['references'],'qa'=>json_decode($qa['checks_json'],true),'limitations'=>array_merge(json_decode($p['body'],true)['limitations'],['Сгенерированный код не выполнялся. JSON — данные, не установленный сайт.']),'acceptance_checklist'=>json_decode($p['source_json'],true)['requirements']];$bytes=ai_json($manifest);$hash=hash('sha256',$bytes);$old=crm_query('SELECT id FROM nd_prod_packages WHERE manifest_hash=?',[$hash])->fetchColumn();if($old)return ['ok'=>true,'id'=>(int)$old];$file=prod_generated_json((int)$p['project_id'],$bytes,$stored,$lock);
  crm_query('INSERT INTO nd_prod_packages(run_id,report_id,bundle_hash,manifest_hash,file_id) VALUES (?,?,?,?,?)',[$run,$qa['id'],$bundle['hash'],$hash,$file]);$id=(int)db()->lastInsertId();prod_event((int)$p['id'],$run,'package_prepared_private');return ['ok'=>true,'id'=>$id,'manifest_hash'=>$hash];
 });}catch(Throwable $e){if($stored)cc_cleanup_upload($stored);throw $e;}finally{if(is_resource($lock)){flock($lock,LOCK_UN);fclose($lock);}}
}
function prod_package_action(int $id,string $action,array $d):array{
 return crm_idempotent('production:package:'.$id.':'.$action,$d,function()use($id,$action,$d){$pkg=crm_query('SELECT * FROM nd_prod_packages WHERE id=?',[$id])->fetch();if(!$pkg)crm_fail(404,'Запись не найдена.');$r=prod_run((int)$pkg['run_id'],true);$pkg=crm_query('SELECT * FROM nd_prod_packages WHERE id=? FOR UPDATE',[$id])->fetch();$p=prod_plan((int)$r['plan_id']);prod_current_source($p,true);if(($d['confirm']??false)!==true||!is_string($d['checksum']??null)||!hash_equals($pkg['manifest_hash'],$d['checksum']))crm_fail(409,'Подтвердите точную редакцию пакета.');
  if($action==='deliver'&&$pkg['state']==='DELIVERED')return ['ok'=>true,'id'=>$id,'revision_id'=>(int)$pkg['revision_id']];crm_version($d,$pkg);$qa=crm_query('SELECT * FROM nd_prod_qa_reports WHERE id=?',[$pkg['report_id']])->fetch();$bundle=prod_bundle((int)$r['id']);$f=cc_file(['type'=>'owner','id'=>1],(int)$pkg['file_id']);cc_file_path($f);if($qa['verdict']!=='PASS'||!hash_equals($bundle['hash'],$pkg['bundle_hash'])||!hash_equals($f['checksum'],$pkg['manifest_hash']))crm_fail(409,'Пакет или QA evidence изменились.');
  if($action==='approve'){
   if($pkg['state']!=='DRAFT'||$r['state']!=='READY')crm_fail(409,'Пакет не готов к одобрению.');crm_query("INSERT INTO nd_prod_decisions(entity,record_id,owner_id,decision,checksum,source_hash) VALUES ('package',?,1,'approved',?,?)",[$id,$pkg['manifest_hash'],$p['source_hash']]);crm_query("UPDATE nd_prod_packages SET state='APPROVED',version=version+1 WHERE id=?",[$id]);prod_event((int)$p['id'],(int)$r['id'],'exact_package_approved');
  }elseif($action==='deliver'){
   if($pkg['state']!=='APPROVED'||$r['state']!=='READY')crm_fail(409,'Сначала одобрите точный пакет.');$decision=crm_query("SELECT * FROM nd_prod_decisions WHERE entity='package' AND record_id=? AND decision='approved'",[$id])->fetch();if(!$decision||!hash_equals($decision['checksum'],$pkg['manifest_hash']))crm_fail(409,'Нет действующего одобрения.');$owner=['type'=>'owner','id'=>1];
   crm_query("UPDATE nd_cc_files SET visibility='customer',version=version+1 WHERE id=?",[$f['id']]);$doc=cc_create_document_effect($owner,(int)$p['project_id'],['kind'=>'deliverable','title'=>'Результат заказа №'.$p['order_id'],'fields'=>['title'=>'Результат заказа №'.$p['order_id'],'description'=>'Пакет JSON: файлы, инструкции и проверенные ограничения.','acceptance'=>'Проверьте содержимое пакета и критерии принятого ТЗ.','comments'=>'Код не запускался на сервере НейроДело.'],'file_ids'=>[(int)$f['id']]]);$ready=cc_ready_effect($owner,(int)$doc['id'],['version'=>(int)$doc['revision']['version']]);cc_submit_effect($owner,(int)$doc['id'],['version'=>(int)$ready['revision']['version'],'confirm'=>true]);
   crm_query("UPDATE nd_prod_packages SET state='DELIVERED',revision_id=?,version=version+1 WHERE id=?",[$doc['id'],$id]);prod_run_state($r,'DELIVERED','delivered_for_customer_review');
  }else crm_fail(404,'Действие не найдено.');return ['ok'=>true,'id'=>$id];
 });
}
